import{_ as n,C as o,o as e,c as i,a0 as r,b as d,w as a,a as p,E as h,a1 as l}from"./chunks/framework.DScjKhBS.js";const w=JSON.parse('{"title":"What SPDD is & the REASONS Canvas","description":"Problem framing, seven-part REASONS structure, and why prompts are first-class delivery artifacts.","frontmatter":{"title":"What SPDD is & the REASONS Canvas","description":"Problem framing, seven-part REASONS structure, and why prompts are first-class delivery artifacts."},"headers":[],"relativePath":"reports/structured-prompt-driven/01-spdd-and-reasons.md","filePath":"reports/structured-prompt-driven/01-spdd-and-reasons.md"}'),c={name:"reports/structured-prompt-driven/01-spdd-and-reasons.md"};function g(u,t,m,v,f,b){const s=o("Mermaid");return e(),i("div",null,[t[1]||(t[1]=r('<h1 id="what-spdd-is-the-reasons-canvas" tabindex="-1">What SPDD is &amp; the REASONS Canvas <a class="header-anchor" href="#what-spdd-is-the-reasons-canvas" aria-label="Permalink to &quot;What SPDD is &amp; the REASONS Canvas&quot;">​</a></h1><p>Individual developers gain speed from LLM assistants, but <strong>delivery throughput</strong> is constrained elsewhere: ambiguous requirements, heavier reviews, integration risk, and harder production reasoning when change volume rises. Structured-Prompt-Driven Development (<strong>SPDD</strong>) responds by making AI-assisted change <strong>governable, reviewable, and reusable</strong> at team scale — not only faster typing.</p><p>Source: <a href="https://martinfowler.com/articles/structured-prompt-driven/" target="_blank" rel="noreferrer">Structured-Prompt-Driven Development (SPDD)</a>, Martin Fowler, 2026.</p><hr><h2 id="definition" tabindex="-1">Definition <a class="header-anchor" href="#definition" aria-label="Permalink to &quot;Definition&quot;">​</a></h2><p><strong>SPDD</strong> is an engineering method that treats <strong>prompts as first-class delivery artifacts</strong>: version-controlled, reviewable, reusable, and improvable. Structured prompts capture requirements, domain language, design intent, constraints, and task breakdown so the model generates code <strong>inside a defined boundary</strong> — output becomes easier to validate and less dependent on ad hoc chat.</p><hr><h2 id="the-reasons-canvas" tabindex="-1">The REASONS Canvas <a class="header-anchor" href="#the-reasons-canvas" aria-label="Permalink to &quot;The REASONS Canvas&quot;">​</a></h2><p>The <strong>REASONS Canvas</strong> is a seven-part structure that guides a prompt from <strong>intent → design → execution → governance</strong>. It exists so the LLM is guided by clarity rather than guesswork; reviewers reason about <strong>one artifact</strong> instead of scattered chat and partial diffs.</p><h3 id="dimensions" tabindex="-1">Dimensions <a class="header-anchor" href="#dimensions" aria-label="Permalink to &quot;Dimensions&quot;">​</a></h3><p><strong>Abstract (intent and design)</strong></p><table tabindex="0"><thead><tr><th>Letter</th><th>Focus</th></tr></thead><tbody><tr><td><strong>R</strong> — Requirements</td><td>Problem statement and definition of done</td></tr><tr><td><strong>E</strong> — Entities</td><td>Domain entities and relationships</td></tr><tr><td><strong>A</strong> — Approach</td><td>Strategy to meet the requirements</td></tr><tr><td><strong>S</strong> — Structure</td><td>Where the change sits; components and dependencies</td></tr></tbody></table><p><strong>Specific (execution)</strong></p><table tabindex="0"><thead><tr><th>Letter</th><th>Focus</th></tr></thead><tbody><tr><td><strong>O</strong> — Operations</td><td>Concrete, testable implementation steps derived from the strategy</td></tr></tbody></table><p><strong>Common standards (governance)</strong></p><table tabindex="0"><thead><tr><th>Letter</th><th>Focus</th></tr></thead><tbody><tr><td><strong>N</strong> — Norms</td><td>Cross-cutting engineering norms (naming, observability, defensive coding, …)</td></tr><tr><td><strong>S</strong> — Safeguards</td><td>Non-negotiable boundaries (invariants, performance limits, security rules, …)</td></tr></tbody></table><p>The article uses <strong>REASONS</strong> as the mnemonic (with <strong>Structure</strong> and the second <strong>S</strong> for <strong>Safeguards</strong>).</p><hr><h2 id="flow-conceptual" tabindex="-1">Flow (conceptual) <a class="header-anchor" href="#flow-conceptual" aria-label="Permalink to &quot;Flow (conceptual)&quot;">​</a></h2>',19)),(e(),d(l,null,{default:a(()=>[h(s,{id:"mermaid-140",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20abstract%20%5BAbstract%5D%0A%20%20%20%20R%5BRequirements%5D%0A%20%20%20%20E%5BEntities%5D%0A%20%20%20%20A%5BApproach%5D%0A%20%20%20%20S1%5BStructure%5D%0A%20%20end%0A%20%20subgraph%20execution%20%5BExecution%5D%0A%20%20%20%20O%5BOperations%5D%0A%20%20end%0A%20%20subgraph%20governance%20%5BGovernance%5D%0A%20%20%20%20N%5BNorms%5D%0A%20%20%20%20S2%5BSafeguards%5D%0A%20%20end%0A%20%20R%20--%3E%20E%20--%3E%20A%20--%3E%20S1%20--%3E%20O%20--%3E%20N%20--%3E%20S2%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[p(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<p>Moving uncertainty <strong>left</strong> — before generation — is the recurring theme: the Canvas holds the full specification so review targets <strong>intent and boundaries</strong>, not only line-level noise.</p><hr><h2 id="prompt-vs-chat" tabindex="-1">Prompt vs chat <a class="header-anchor" href="#prompt-vs-chat" aria-label="Permalink to &quot;Prompt vs chat&quot;">​</a></h2><p>Compared to disposable chat:</p><ul><li>The prompt <strong>persists</strong> as the record of what was intended.</li><li>It spans <strong>requirements through safeguards</strong>, not only “what the system should do”.</li><li><strong>Prompt and code stay synchronised</strong> when either side changes (see <a href="./reports/structured-prompt-driven/02-openspdd-and-workflow.html">Workflow &amp; openspdd</a>).</li></ul><hr><h2 id="relation-to-spec-driven-development" tabindex="-1">Relation to spec-driven development <a class="header-anchor" href="#relation-to-spec-driven-development" aria-label="Permalink to &quot;Relation to spec-driven development&quot;">​</a></h2><p>SPDD shares “spec before code” with spec-driven approaches but adds <strong>how</strong> the spec is produced, reviewed, and kept aligned with code — with <strong>REASONS</strong> plus workflow automation. The Fowler article frames this as <strong>spec-anchored</strong> practice (see Birgitta Böckeler’s categorisation in the original piece).</p><hr><p><strong>Next:</strong> <a href="./reports/structured-prompt-driven/02-openspdd-and-workflow.html">Workflow &amp; openspdd commands</a></p>',10))])}const A=n(c,[["render",g]]);export{w as __pageData,A as default};
